svg.script:
(() => {
    'use strict';
    const root = document.documentElement;
    const layer = document.getElementById('logotype');
    const fallback = document.getElementById('fallback');
    const definitions = document.getElementById('flap-definitions');
    const word = 'infrastructure';
    const count = word.length - 2;
    const params = new URLSearchParams(window.location.search);
    const clamp = (value, min, max) => Math.min(max, Math.max(min, value));
    const numeric = (value, min, max, fallback) => Number.isFinite(Number(value))
        ? clamp(Number(value), min, max) : fallback;
    const variant = Math.round(numeric(params.get('variant') || 0, 0, 6, 0));
    const flagVariant = variant === 5 || variant === 6;
    const swapVariant = variant === 6;
    const flagFace = '@eu-flag';
    const euFlagBlue = '#003399';
    // Native proportions; RGB approximates cloth standards where necessary.
    const countryFlags = {
        NL: { width: 3, height: 2, stripes: 'horizontal', colors: ['#ae1c28', '#ffffff', '#21468b'] },
        DE: { width: 5, height: 3, stripes: 'horizontal', colors: ['#000000', '#ff0000', '#ffcc00'] },
        FR: { width: 3, height: 2, stripes: 'vertical', colors: ['#002654', '#ffffff', '#ed2939'] },
        LU: { width: 5, height: 3, stripes: 'horizontal', colors: ['#ef3340', '#ffffff', '#00a3e0'] },
        CH: { width: 32, height: 32, colors: ['#ff0000', '#ffffff'] },
        DK: { width: 37, height: 28, colors: ['#c8102e', '#ffffff'] },
    };
    const countryFor = (value, fallback = 'NL') => typeof value === 'string'
        && Object.hasOwn(countryFlags, value.toUpperCase()) ? value.toUpperCase() : fallback;
    const flagTravelDelay = 0.1; // Join the flag before its leftward travel begins.
    // Permanent counter cards add two places even after every letter is revealed.
    const capacity = word.length + (flagVariant ? 2 : 1);
    const lastModelStep = count;
    const preview = params.get('preview') === '1';
    const motionPreference = matchMedia('(prefers-reduced-motion: reduce)');
    const clock = () => performance.timeOrigin + performance.now();
    const mix = (a, b, progress) => a + (b - a) * progress;
    function normalizeColor(value) {
        if (typeof value !== 'string') return null;
        const hex = value.trim().toLowerCase();
        if (/^#[\da-f]{3}$/.test(hex)) return '#' + [...hex.slice(1)].map(digit => digit + digit).join('');
        return /^#[\da-f]{6}$/.test(hex) ? hex : null;
    }
    function mixColor(from, to, progress) {
        if (progress <= 0) return from;
        if (progress >= 1) return to;
        return '#' + [1, 3, 5].map(index => Math.round(mix(
            parseInt(from.slice(index, index + 2), 16),
            parseInt(to.slice(index, index + 2), 16), progress,
        )).toString(16).padStart(2, '0')).join('');
    }
    const milliseconds = value => parseFloat(value) * (/ms\s*$/.test(value) ? 1 : 1000);
    let config, ease, duration, expansionEnd, collapseStart, collapseEnd, loopStartTime, hasCollapse;
    let characterAdvance, flapAdvance, glyphWidth, tileWidth, tileHeight, baseline;
    let flagArtwork, joinedFlag, loopFlagCover, drawFlagFold, solidClips = [];
    let models = [], sprites = new Map();
    let playing = false, position = 0, startedAt = 0, originTime = 0, frame = 0;
    let lastPublished = -Infinity, ready = false;
    let flagFrame = 0;
    const flagRun = { phase: 'idle', country: 'NL', startedAt: 0 };

    function create(tag, attributes = {}, parent = layer) {
        const element = document.createElementNS('http://www.w3.org/2000/svg', tag);
        for (const [name, value] of Object.entries(attributes)) element.setAttribute(name, value);
        parent.append(element);
        return element;
    }

    function readDefaults() {
        const css = getComputedStyle(root);
        const value = name => css.getPropertyValue(name).trim();
        return {
            transitionDuration: milliseconds(value('--transition-duration')),
            holdDuration: milliseconds(value('--hold-duration')),
            expandedHoldDuration: numeric(milliseconds(value('--expanded-hold-duration')), 0, 10000, 2500),
            loopDuration: milliseconds(value('--loop-duration')),
            collapsedHoldDuration: numeric(milliseconds(value('--collapsed-hold-duration')), 0, 10000, 2500),
            easing: value('--easing'), fontSize: parseFloat(value('--font-size')),
            characterSpacing: parseFloat(value('--character-spacing')),
            flapWidth: numeric(parseFloat(value('--flap-width')), 0.6, 2, 0.85),
            flapHeight: parseFloat(value('--flap-height')),
            flapGap: parseFloat(value('--flap-gap')),
            flapOuterGap: numeric(parseFloat(value('--flap-outer-gap')), 0, 96, 4),
            leadingFlagGap: numeric(parseFloat(value('--leading-flag-gap')), 0, 96, 16),
            starScale: numeric(value('--eu-star-scale') || 1, 0.25, 4, 1),
            flapColor: normalizeColor(value('--flap-color')) || '#000000',
            textColor: normalizeColor(value('--text-color')) || '#000000',
            flapTextColor: normalizeColor(value('--flap-text-color')) || '#f8faff',
            detailColor: normalizeColor(value('--flap-detail-color')) || '#ffffff',
            detailOpacity: numeric(value('--flap-detail-opacity') || 1, 0, 1, 1),
            detailsVisible: value('--flap-details-visible') !== '0',
            backgroundColor: normalizeColor(value('--background-color')) || '#ffffff',
            loop: value('--loop') === '1',
            flagCountry: countryFor(value('--flag-country')),
            flagReturnMode: value('--flag-return-mode') === 'manual' ? 'manual' : 'auto',
            flagHoldDuration: numeric(milliseconds(value('--flag-hold-duration')), 0, 10000, 5000),
        };
    }

    // One easing function drives position, opacity, and the two-stage hinge.
    // Bisection solves CSS cubic-bezier's x coordinate, rather than treating
    // its parameter as elapsed time. Reject unsupported curves atomically.
    function easingFor(value) {
        const presets = {
            linear: [0, 0, 1, 1], ease: [0.25, 0.1, 0.25, 1],
            'ease-in': [0.42, 0, 1, 1], 'ease-out': [0, 0, 0.58, 1],
            'ease-in-out': [0.42, 0, 0.58, 1],
        };
        const match = /^cubic-bezier\(([^)]+)\)$/.exec(value);
        const points = presets[value] || (match && match[1].split(',').map(Number));
        if (!points || points.length !== 4 || !points.every(Number.isFinite)
            || points.some(number => number < 0 || number > 1)) return null;
        const [x1, y1, x2, y2] = points;
        const curve = (t, a, b) => 3 * (1 - t) ** 2 * t * a + 3 * (1 - t) * t * t * b + t ** 3;
        return progress => {
            if (progress <= 0 || progress >= 1) return clamp(progress, 0, 1);
            let low = 0, high = 1;
            for (let i = 0; i < 24; i++) {
                const middle = (low + high) / 2;
                if (curve(middle, x1, x2) < progress) low = middle;
                else high = middle;
            }
            return curve((low + high) / 2, y1, y2);
        };
    }

    function stateAt(remaining, padded = variant > 1) {
        if (!remaining) return word;
        const digits = padded ? String(remaining).padStart(2, '0') : String(remaining);
        return word[0] + digits + word.slice(remaining + 1);
    }

    function layout(remaining, swapped = false) {
        const state = new Map();
        if (variant === 3 || variant === 4) {
            const text = stateAt(remaining);
            const cells = variant === 4 ? text.padEnd(capacity, ' ') : text;
            [...cells].forEach((character, index) => state.set(`cell:${index}`, { character, x: index * flapAdvance }));
        } else {
            // The visible-digits variant drops the tens card below ten.
            // Other split-flap counters keep both places until their final turn.
            const digits = remaining ? String(remaining).padStart(variant > 1 ? 2 : 1, '0')
                : flagVariant ? '00' : '';
            const digitWidth = variant === 0 ? glyphWidth : tileWidth;
            const digitAdvance = variant === 0 ? characterAdvance : swapped ? tileWidth : flapAdvance;
            const counterWidth = digits.length ? digitWidth + (digits.length - 1) * digitAdvance : 0;
            // Flap boundaries have their own spacing. After the flag leads,
            // the i joins the plain word, so its next gap uses letter tracking.
            const outerGap = swapped ? config.leadingFlagGap
                : variant > 0 && digits.length ? config.flapOuterGap : config.characterSpacing;
            const counterX = glyphWidth + outerGap;
            const suffixX = swapped ? counterWidth + outerGap + characterAdvance
                : digits.length ? counterX + counterWidth + outerGap : characterAdvance;
            state.set('letter:0', { character: word[0], x: swapped ? counterWidth + outerGap : 0 });
            for (let index = remaining + 1; index < word.length; index++) {
                state.set(`letter:${index}`, { character: word[index], x: suffixX + (index - remaining - 1) * characterAdvance });
            }
            [...digits].forEach((character, index) => state.set(`digit:${index}`, {
                character: flagVariant && remaining === 0 ? flagFace : character,
                x: (swapped ? 0 : counterX) + index * digitAdvance,
            }));
        }
        return state;
    }

    function makeFlagArtwork() {
        // One shared circle spans both cards. Each half-face clips its own
        // translated copy, so neither the stars nor a background can bridge
        // the existing gap. Fit the EU's 3:2 reference within custom cards.
        const pairWidth = flapAdvance + tileWidth;
        const referenceHeight = Math.min(tileHeight, pairWidth / 1.5);
        const ringRadius = referenceHeight / 3 * config.starScale;
        const starRadius = referenceHeight / 18 * config.starScale;
        const innerRadius = starRadius * Math.sin(Math.PI / 10) / Math.sin(3 * Math.PI / 10);
        const cx = pairWidth / 2, cy = tileHeight / 2;
        const stars = flagArtwork = create('g', {
            id: 'eu-flag-stars', fill: '#ffcc00', 'data-ring-radius': ringRadius,
            'data-star-radius': starRadius, 'data-center-x': cx, 'data-center-y': cy,
        }, definitions);
        for (let star = 0; star < 12; star++) {
            const angle = -Math.PI / 2 + star * Math.PI / 6;
            const x = cx + ringRadius * Math.cos(angle), y = cy + ringRadius * Math.sin(angle);
            const points = Array.from({ length: 10 }, (_, point) => {
                const radius = point % 2 ? innerRadius : starRadius;
                // Every star points up, independently of its ring position.
                const direction = -Math.PI / 2 + point * Math.PI / 5;
                return `${x + radius * Math.cos(direction)},${y + radius * Math.sin(direction)}`;
            }).join(' ');
            create('polygon', { points, 'data-star': star }, stars);
        }
    }

    function makeCountryFlags() {
        const width = 2 * tileWidth;
        for (const [country, flag] of Object.entries(countryFlags)) {
            // Uniform cover scaling keeps crosses proportionate in custom cards.
            const scale = Math.max(width / flag.width, tileHeight / flag.height);
            // Compose the stripes/cross into one paint before clipping a leaf;
            // separately clipped colors can leave a hairline at the hinge.
            const paint = create('pattern', {
                id: `flag-country-${country}-paint`, patternUnits: 'userSpaceOnUse',
                width, height: tileHeight,
            }, definitions);
            const artwork = create('g', {
                transform: `translate(${width / 2} ${tileHeight / 2}) scale(${scale}) translate(${-flag.width / 2} ${-flag.height / 2})`,
            }, paint);
            const rectangle = (x, y, w, h, fill) => create('rect', { x, y, width: w, height: h, fill }, artwork);
            rectangle(0, 0, flag.width, flag.height, flag.colors[0]);
            if (flag.stripes) {
                flag.colors.slice(1).forEach((color, index) => {
                    const stripe = index + 1;
                    if (flag.stripes === 'vertical') rectangle(stripe * flag.width / 3, 0, flag.width / 3, flag.height, color);
                    else rectangle(0, stripe * flag.height / 3, flag.width, flag.height / 3, color);
                });
            } else if (country === 'CH') {
                rectangle(13, 6, 6, 20, flag.colors[1]);
                rectangle(6, 13, 20, 6, flag.colors[1]);
            } else if (country === 'DK') {
                rectangle(12, 0, 4, 28, flag.colors[1]);
                rectangle(0, 12, 37, 4, flag.colors[1]);
            }
            const surface = create('g', { id: `flag-country-${country}`, 'data-country': country }, definitions);
            create('rect', { width, height: tileHeight, fill: `url(#flag-country-${country}-paint)` }, surface);
        }
    }

    function makeFlagFold() {
        const half = tileHeight / 2;
        const full = create('g', { id: 'flag-interaction-eu' }, definitions);
        create('rect', { width: 2 * tileWidth, height: tileHeight, class: 'eu-flag-surface' }, full);
        create('use', { href: '#eu-flag-stars' }, full);
        for (const [part, y] of [['top', 0], ['bottom', half]]) {
            const clip = create('clipPath', { id: `flag-fold-${part}`, clipPathUnits: 'userSpaceOnUse' }, definitions);
            create('rect', { y, width: 2 * tileWidth, height: half }, clip);
        }
        const fold = create('g', { 'data-flag-fold': 'true' }, joinedFlag);
        // A complete backing prevents transparent seams beneath the rotating leaves.
        const previousBacking = create('use', { display: 'none' }, fold);
        const backing = create('use', { href: '#flag-interaction-eu' }, fold);
        const revealClip = create('clipPath', { id: 'flag-fold-reveal', clipPathUnits: 'userSpaceOnUse' }, definitions);
        const revealMask = create('rect', { width: 2 * tileWidth, height: tileHeight }, revealClip);
        backing.setAttribute('clip-path', 'url(#flag-fold-reveal)');
        function leaf(part) {
            const wrapper = create('g', {}, fold);
            const clipped = create('g', { 'clip-path': `url(#flag-fold-${part})` }, wrapper);
            const artwork = create('use', {}, clipped);
            return { wrapper, artwork };
        }
        const bottom = leaf('bottom'), outgoing = leaf('top'), incoming = leaf('bottom');
        const bottomClip = create('clipPath', { id: 'flag-fold-old-bottom', clipPathUnits: 'userSpaceOnUse' }, definitions);
        const bottomMask = create('rect', { y: half, width: 2 * tileWidth, height: half }, bottomClip);
        bottom.wrapper.setAttribute('clip-path', 'url(#flag-fold-old-bottom)');
        outgoing.wrapper.dataset.face = 'flag-outgoing-top';
        incoming.wrapper.dataset.face = 'flag-incoming-bottom';
        const href = country => country === 'EU' ? '#flag-interaction-eu' : `#flag-country-${country}`;
        return (before, after, progress) => {
            const turning = before !== after && progress > 0 && progress < 1;
            backing.setAttribute('href', href(progress <= 0 ? before : after));
            bottom.artwork.setAttribute('href', href(before));
            outgoing.artwork.setAttribute('href', href(before));
            incoming.artwork.setAttribute('href', href(after));
            const topScale = turning && progress < 0.5 ? Math.cos(progress * Math.PI) : 0;
            const bottomScale = turning && progress >= 0.5 ? Math.sin((progress - 0.5) * Math.PI) : 0;
            // Reveal the incoming top only above the falling leaf. Its color
            // must not peek through the two old half-faces at the hinge.
            previousBacking.setAttribute('href', href(before));
            previousBacking.setAttribute('display', topScale > 0 ? 'inline' : 'none');
            revealMask.setAttribute('height', topScale > 0 ? half * (1 - topScale) : tileHeight);
            // Remove the covered old face too, so its color cannot fringe
            // through the incoming leaf's antialiased edge at the hinge.
            bottomMask.setAttribute('y', half + half * bottomScale);
            bottomMask.setAttribute('height', half * (1 - bottomScale));
            bottom.wrapper.setAttribute('display', turning ? 'inline' : 'none');
            outgoing.wrapper.setAttribute('display', topScale > 0.00001 ? 'inline' : 'none');
            incoming.wrapper.setAttribute('display', bottomScale > 0.00001 ? 'inline' : 'none');
            outgoing.wrapper.setAttribute('transform', `translate(0 ${half}) scale(1 ${topScale}) translate(0 ${-half})`);
            incoming.wrapper.setAttribute('transform', `translate(0 ${half}) scale(1 ${bottomScale}) translate(0 ${-half})`);
            fold.dataset.from = before;
            fold.dataset.to = after;
            fold.dataset.progress = String(progress);
        };
    }

    function roundedCardPath(x, width, leftRadius, rightRadius) {
        return `M ${x + leftRadius} 0 H ${x + width - rightRadius}
            A ${rightRadius} ${rightRadius} 0 0 1 ${x + width} ${rightRadius}
            V ${tileHeight - rightRadius} A ${rightRadius} ${rightRadius} 0 0 1 ${x + width - rightRadius} ${tileHeight}
            H ${x + leftRadius} A ${leftRadius} ${leftRadius} 0 0 1 ${x} ${tileHeight - leftRadius}
            V ${leftRadius} A ${leftRadius} ${leftRadius} 0 0 1 ${x + leftRadius} 0 Z`;
    }

    function updateFlagGeometry(progress, visible, x) {
        const originalWidth = tileWidth + flapAdvance;
        const pairWidth = tileWidth + mix(flapAdvance, tileWidth, progress);
        // Keep the whole star circle centred and uniformly scaled as the gap
        // closes. Translating two fixed crops would break the circular artwork.
        const scale = Math.min(tileHeight, pairWidth / 1.5) / Math.min(tileHeight, originalWidth / 1.5);
        flagArtwork.setAttribute('transform', `translate(${pairWidth / 2} ${tileHeight / 2}) scale(${scale}) translate(${-originalWidth / 2} ${-tileHeight / 2})`);
        solidClips.forEach((path, column) => path.setAttribute('d', flapOutline(column, progress)));
        // The shared face travels beneath the outgoing digits. Separate card
        // clips can expose antialiased seams even when their numeric gap is zero.
        joinedFlag.setAttribute('display', visible ? 'inline' : 'none');
        joinedFlag.setAttribute('transform', `translate(${x} 0)`);
        root.dataset.flagGap = String(pairWidth - 2 * tileWidth);
    }

    function flapOutline(column, progress) {
        const radius = config.fontSize * 0.045;
        return roundedCardPath(0, tileWidth,
            column === 0 ? radius : radius * (1 - progress),
            column === 1 ? radius : radius * (1 - progress));
    }

    function text(character, parent, attributes = {}) {
        const node = create('text', { x: glyphWidth / 2, y: baseline, 'text-anchor': 'middle', ...attributes }, parent);
        node.textContent = character;
        return node;
    }

    function makePlain(parent) {
        const outgoing = text('', parent), incoming = text('', parent);
        return (before, after, progress) => {
            outgoing.textContent = before;
            incoming.textContent = after;
            outgoing.setAttribute('opacity', before === after ? 1 : 1 - progress);
            incoming.setAttribute('opacity', before === after ? 0 : progress);
        };
    }

    function makeFlap(parent, column) {
        const tile = create('g', { 'data-flap': 'true' }, parent);
        if (swapVariant) tile.setAttribute('clip-path', `url(#flap-solid-${column})`);
        const half = tileHeight / 2;
        function face(part) {
            // Transform the wrapper AFTER clipping its child, so the glyph
            // and its half-card rotate together about the centre hinge.
            const wrapper = create('g', {}, tile);
            const clipped = create('g', { 'clip-path': `url(#flap-${part})` }, wrapper);
            const surface = swapVariant ? create('path', { class: 'flap-surface' }, clipped)
                : create('rect', { width: tileWidth, height: tileHeight, rx: config.fontSize * 0.045, class: 'flap-surface' }, clipped);
            const glyph = text('', clipped, { x: tileWidth / 2, class: 'flap-text' });
            const shadow = create('rect', { width: tileWidth, height: tileHeight, fill: '#000', opacity: 0 }, clipped);
            // Artwork belongs to the rotating face, just like the digits.
            // Draw stars above the shade to retain their specified yellow.
            const stars = flagVariant && Number.isInteger(column)
                ? create('use', { href: '#eu-flag-stars', transform: `translate(${-column * flapAdvance} 0)`, display: 'none' }, clipped)
                : null;
            return { wrapper, surface, glyph, shadow, stars };
        }
        function setFace(face, content) {
            const flag = content === flagFace;
            face.surface.setAttribute('class', flag ? 'eu-flag-surface' : 'flap-surface');
            face.glyph.textContent = flag ? '' : content;
            if (face.stars) face.stars.setAttribute('display', flag ? 'inline' : 'none');
        }
        const top = face('top'), bottom = face('bottom');
        const fallingTop = face('top'), arrivingBottom = face('bottom');
        let bottomMask;
        if (swapVariant) {
            const clip = create('clipPath', { id: `flap-outgoing-bottom-${column}`, clipPathUnits: 'userSpaceOnUse' }, definitions);
            bottomMask = create('rect', { y: half, width: tileWidth, height: half }, clip);
            bottom.wrapper.setAttribute('clip-path', `url(#flap-outgoing-bottom-${column})`);
        }
        fallingTop.wrapper.dataset.face = 'outgoing-top';
        arrivingBottom.wrapper.dataset.face = 'incoming-bottom';
        const details = create('g', { 'data-flap-details': 'true' }, tile);
        create('rect', { x: 0, y: half - 0.55, width: tileWidth, height: 1.1, class: 'flap-detail' }, details);
        for (const x of [0, tileWidth - 1.5]) {
            create('rect', { x, y: half - 2, width: 1.5, height: 4, rx: 0.5, class: 'flap-detail' }, details);
        }
        let previousPair = '';
        return (before, after, progress, cleanupProgress = 0, settledTopShade = 0.025) => {
            const formingFlag = swapVariant && before !== after && after === flagFace;
            details.setAttribute('opacity', swapVariant ? 1 - cleanupProgress : 1);
            if (swapVariant) {
                const offset = -column * mix(flapAdvance, tileWidth, cleanupProgress);
                // The face silhouettes close their inner corners too; changing
                // only the outer clip would leave a notch in the blue surfaces.
                for (const face of [top, bottom, fallingTop, arrivingBottom]) {
                    face.surface.setAttribute('d', flapOutline(column, cleanupProgress));
                }
                for (const stars of [top.stars, bottom.stars, fallingTop.stars, arrivingBottom.stars]) {
                    stars.setAttribute('transform', `translate(${offset} 0)`);
                }
            }
            const changing = before !== after;
            const pair = `${before}\0${after}`;
            if (pair !== previousPair) {
                // New top and old bottom are stationary underneath the leaf.
                setFace(top, after);
                setFace(bottom, before);
                setFace(fallingTop, before);
                setFace(arrivingBottom, after);
                previousPair = pair;
            }
            // Orthographic projection of a leaf rotating around its X axis:
            // outgoing top 0..90 degrees, then incoming bottom -90..0.
            const topScale = changing && progress < 0.5 ? Math.cos(progress * Math.PI) : 0;
            const bottomScale = changing && progress >= 0.5 ? Math.sin((progress - 0.5) * Math.PI) : 0;
            fallingTop.wrapper.setAttribute('transform', `translate(0 ${half}) scale(1 ${topScale}) translate(0 ${-half})`);
            arrivingBottom.wrapper.setAttribute('transform', `translate(0 ${half}) scale(1 ${bottomScale}) translate(0 ${-half})`);
            fallingTop.wrapper.setAttribute('display', topScale > 0.00001 ? 'inline' : 'none');
            top.wrapper.setAttribute('display', formingFlag ? 'none' : 'inline');
            arrivingBottom.wrapper.setAttribute('display', !formingFlag && bottomScale > 0.00001 ? 'inline' : 'none');
            if (bottomMask) {
                // Match the incoming leaf's reveal boundary, but expose the
                // continuous flag below instead of painting separate star crops.
                const revealed = formingFlag ? half * bottomScale : 0;
                bottomMask.setAttribute('y', half + revealed);
                bottomMask.setAttribute('height', half - revealed);
            }
            // Mechanical shading must not tint the flag's specified blue.
            fallingTop.shadow.setAttribute('opacity', formingFlag || before === flagFace ? 0 : (1 - topScale) * 0.28);
            // Settle the returning digit into its stationary shade so the
            // loop boundary cannot brighten/darken custom-coloured cards.
            const arrivingShade = (1 - bottomScale) * 0.28
                + (swapVariant && before === flagFace ? bottomScale * 0.07 : 0);
            arrivingBottom.shadow.setAttribute('opacity', after === flagFace ? 0 : arrivingShade);
            top.shadow.setAttribute('opacity', after === flagFace ? 0 : settledTopShade);
            const bottomContent = !changing || progress >= 1 ? after : before;
            bottom.shadow.setAttribute('opacity', formingFlag || bottomContent === flagFace ? 0 : 0.07);
            // Holds (including p=1 when manually sampled) show the new face.
            setFace(bottom, bottomContent);
            tile.dataset.flipping = String(changing && progress > 0 && progress < 1);
            const content = progress < 0.5 ? before : after;
            tile.dataset.empty = String(content === flagFace || content.trim() === '');
            tile.dataset.flag = String(content === flagFace);
        };
    }

    const automaticColors = {backgroundColor: true, textColor: true};
    let appearanceColors = null;
    function applyAutomaticColors() {
        if (!appearanceColors) return;
        for (const key of Object.keys(automaticColors)) {
            if (automaticColors[key]) config[key] = appearanceColors[key];
        }
    }
    function applyAppearance(data) {
        if (!['light', 'dark'].includes(data.theme)) return;
        const backgroundColor = normalizeColor(data.colors?.backgroundColor);
        const textColor = normalizeColor(data.colors?.textColor);
        if (!backgroundColor || !textColor) return;
        appearanceColors = {backgroundColor, textColor};
        applyAutomaticColors();
        applyColors();
        publish();
    }

    function applyColors() {
        root.style.setProperty('--flap-color', config.flapColor);
        root.style.setProperty('--flap-detail-color', config.detailColor);
        root.style.setProperty('--flap-detail-opacity', String(config.detailOpacity));
        root.style.setProperty('--flap-detail-display', config.detailsVisible ? 'inline' : 'none');
        root.style.setProperty('--background-color', config.backgroundColor);
        root.style.setProperty('--text-color', config.textColor);
        root.style.setProperty('--flap-text-color', config.flapTextColor);
    }

    function build() {
        layer.replaceChildren();
        definitions.replaceChildren();
        sprites = new Map();
        solidClips = [];
        root.style.setProperty('--font-size', `${config.fontSize}px`);
        root.style.setProperty('--character-spacing', `${config.characterSpacing}px`);
        applyColors();
        const measure = create('text');
        measure.textContent = 'M';
        glyphWidth = measure.getComputedTextLength();
        measure.remove();
        tileWidth = config.fontSize * config.flapWidth;
        tileHeight = config.fontSize * (variant === 0 ? 1.42 : config.flapHeight);
        // Text and cards use independent pitches. Changing a card's width
        // shifts the following text block without spreading its letters apart.
        characterAdvance = glyphWidth + config.characterSpacing;
        flapAdvance = tileWidth + config.fontSize * config.flapGap;
        baseline = tileHeight / 2 + config.fontSize * 0.32;
        root.dataset.characterAdvance = String(characterAdvance);
        root.dataset.flapAdvance = String(flapAdvance);
        root.dataset.flapWidth = String(tileWidth);
        root.dataset.flapHeight = String(tileHeight);
        root.dataset.variant = String(variant);
        // Comparison previews share the collapse timeline and then hold their
        // initial state. Standalone alternatives do not acquire a collapse.
        hasCollapse = config.loop && (swapVariant || preview);
        expansionEnd = count * (config.holdDuration + config.transitionDuration);
        collapseStart = expansionEnd + config.expandedHoldDuration;
        collapseEnd = collapseStart + (hasCollapse ? config.loopDuration : 0);
        duration = collapseEnd + (hasCollapse ? config.collapsedHoldDuration : 0);
        // The collapsed hold replaces the initial step hold on automatic repeats.
        // Loading and Restart still begin at zero with the original startup timing.
        loopStartTime = hasCollapse ? config.holdDuration : 0;
        ease = easingFor(config.easing) || easingFor('ease-in-out');

        for (const [part, y] of [['top', 0], ['bottom', tileHeight / 2]]) {
            const clip = create('clipPath', { id: `flap-${part}`, clipPathUnits: 'userSpaceOnUse' }, definitions);
            create('rect', { x: 0, y, width: tileWidth, height: tileHeight / 2 }, clip);
        }
        if (swapVariant) {
            for (const column of [0, 1]) {
                const clip = create('clipPath', { id: `flap-solid-${column}`, clipPathUnits: 'userSpaceOnUse' }, definitions);
                solidClips.push(create('path', {}, clip));
            }
            const joinedClip = create('clipPath', { id: 'flag-joined', clipPathUnits: 'userSpaceOnUse' }, definitions);
            create('rect', { width: 2 * tileWidth, height: tileHeight, rx: config.fontSize * 0.045 }, joinedClip);
        }
        if (flagVariant) makeFlagArtwork();
        models = Array.from({ length: count + 1 }, (_, step) => layout(count - step, swapVariant && step === count));
        if (swapVariant) {
            // Paint a single flag first; outgoing digit faces above it mask
            // and reveal the artwork without a white seam during movement.
            joinedFlag = create('g', { 'data-joined-flag': 'true', 'clip-path': 'url(#flag-joined)', display: 'none' });
            makeCountryFlags();
            drawFlagFold = makeFlagFold();
        }
        const keys = new Set(models.flatMap(model => [...model.keys()]));
        for (const key of keys) {
            const group = create('g', { 'data-key': key });
            const digit = key.startsWith('digit:');
            const flapped = variant === 3 || variant === 4 || (variant > 0 && digit);
            sprites.set(key, { group, flapped, draw: flapped ? makeFlap(group, digit ? Number(key.split(':')[1]) : null) : makePlain(group) });
        }
        if (swapVariant) {
            layer.append(sprites.get('letter:0').group);
            // During the text return, letters pass behind one seamless flag.
            loopFlagCover = create('g', { 'data-loop-flag': 'true', 'clip-path': 'url(#flag-joined)', display: 'none' });
            create('use', { href: '#flag-interaction-eu' }, loopFlagCover);
        }
        const canvasHeight = preview ? 180 : 1000;
        root.setAttribute('viewBox', `0 0 1000 ${canvasHeight}`);
        root.setAttribute('height', canvasHeight);
        document.getElementById('background').setAttribute('height', canvasHeight);
        // Keep the reference origin in standalone mode; add preview gutters.
        const inset = preview ? 24 : 0;
        // Fit the widest actual state, keeping scale stable across the animation.
        const contentWidth = Math.max(...models.flatMap(model => [...model].map(([key, cell]) =>
            cell.x + (sprites.get(key).flapped ? tileWidth : glyphWidth))));
        const scale = Math.min(1, (1000 - inset * 2) / contentWidth, (canvasHeight - inset * 2) / tileHeight);
        const y = preview ? (canvasHeight - tileHeight * scale) / 2
            : Math.max(0, config.fontSize * 55 / 48 - baseline) * scale;
        layer.setAttribute('transform', `translate(${inset} ${y}) scale(${scale})`);
        root.dataset.fitScale = String(scale);
        root.dataset.contentWidth = String(contentWidth);
        fallback.setAttribute('visibility', 'hidden');
        layer.setAttribute('visibility', 'visible');
    }

    function currentTime() {
        if (!playing) return position;
        const elapsed = originTime + Math.max(0, clock() - startedAt);
        return config.loop && elapsed >= duration
            ? loopStartTime + (elapsed - duration) % (duration - loopStartTime)
            : Math.min(duration, elapsed);
    }

    function sample(time) {
        const stepDuration = config.holdDuration + config.transitionDuration;
        const step = Math.min(lastModelStep, Math.floor(time / stepDuration));
        const progress = step === lastModelStep ? 0 : clamp((time - step * stepDuration - config.holdDuration) / config.transitionDuration, 0, 1);
        return { step, progress, eased: ease(progress) };
    }

    function sampleReturn(time) {
        if (!swapVariant || !hasCollapse || time < collapseStart || time >= collapseEnd) return null;
        const elapsed = time - collapseStart;
        const segmentDuration = config.loopDuration / 2;
        return elapsed < segmentDuration
            ? { phase: 'text', progress: elapsed / segmentDuration }
            : { phase: 'flaps', progress: (elapsed - segmentDuration) / segmentDuration };
    }

    function render(time) {
        if (swapVariant) loopFlagCover.setAttribute('display', 'none');
        // The exact boundary shares the initial render, including hidden faces.
        if (config.loop && time >= duration) {
            renderCountdown(0);
            root.dataset.loopPhase = 'complete';
            return;
        }
        if (hasCollapse && time >= collapseEnd) {
            renderCountdown(0);
            root.dataset.loopPhase = 'hold';
            return;
        }
        const returning = sampleReturn(time);
        if (returning) renderReturn(returning);
        else renderCountdown(time);
    }

    function renderReturn({ phase, progress }) {
        renderCountdown(expansionEnd);
        const final = models[count], initial = models[0];
        const eased = ease(progress);
        const compactEX = initial.get(`letter:${word.length - 1}`).x - (flapAdvance - tileWidth);
        const flagX = phase === 'text' ? mix(0, initial.get('digit:0').x, eased) : initial.get('digit:0').x;
        const shift = final.get(`letter:${word.length - 1}`).x - compactEX;
        const cleanup = phase === 'text' ? 1 : 1 - eased;
        updateFlagGeometry(cleanup, false, flagX);
        for (const [key, sprite] of sprites) {
            let x, alpha;
            if (key.startsWith('digit:')) {
                const column = Number(key.split(':')[1]);
                x = flagX + column * mix(tileWidth, flapAdvance, 1 - cleanup);
                alpha = phase === 'flaps' && progress > 0 ? 1 : 0;
                // At the initial hold, a changing digit's top is its unshaded
                // outgoing leaf. Match that paint before the timeline wraps.
                const topShade = initial.get(key).character === models[1].get(key).character ? 0.025 : 0;
                sprite.draw(flagFace, initial.get(key).character, phase === 'flaps' ? eased : 0, cleanup, topShade);
            } else {
                const index = Number(key.split(':')[1]);
                if (index === 0) {
                    // Match the earlier i crossing: fade out, change sides while
                    // invisible, then reveal on the same baseline.
                    x = phase === 'text' && progress < 0.5
                        ? Math.max(flagX, final.get(key).x - shift * eased) : initial.get(key).x;
                    alpha = phase === 'flaps' ? 1 : ease(progress < 0.5 ? 1 - 2 * progress : 2 * progress - 1);
                } else if (index === word.length - 1) {
                    x = phase === 'text' ? mix(final.get(key).x, compactEX, eased)
                        : mix(compactEX, initial.get(key).x, eased);
                    alpha = 1;
                } else {
                    // Carry every disappearing glyph fully inside the flag,
                    // including when a custom outer gap leaves the final e far away.
                    x = Math.max(flagX, final.get(key).x
                        - (shift + config.flapOuterGap) * (phase === 'text' ? eased : 1));
                    // Use the i's fade-out curve locally as each letter crosses
                    // the edge, instead of fading the whole word at once.
                    const flagRight = flagX + 2 * tileWidth;
                    const remaining = clamp((x - flagRight + glyphWidth) / (2 * glyphWidth), 0, 1);
                    alpha = phase === 'text' ? ease(remaining) : 0;
                }
                sprite.draw(word[index], word[index], 0);
            }
            sprite.group.setAttribute('transform', `translate(${x} 0)`);
            sprite.group.setAttribute('opacity', alpha);
            sprite.group.setAttribute('display', alpha > 0 ? 'inline' : 'none');
        }
        loopFlagCover.setAttribute('transform', `translate(${flagX} 0)`);
        loopFlagCover.setAttribute('display', phase === 'text' || progress === 0 ? 'inline' : 'none');
        root.style.setProperty('--rendered-flap-color', config.flapColor);
        root.dataset.loopPhase = phase;
        root.dataset.state = phase === 'flaps' ? 'i12e' : word;
        root.dataset.displayState = phase === 'flaps' ? 'i12e' : 'i  e';
        root.dataset.swapProgress = String(phase === 'text' ? 1 - eased : 0);
        root.dataset.flagCleanupProgress = String(cleanup);
    }

    function renderCountdown(time) {
        root.dataset.loopPhase = 'none';
        const { step, progress, eased } = sample(time);
        // Blend outgoing countdown faces during the last turn. Incoming flag
        // faces are always EU blue; sampling keeps edits and seeks deterministic.
        const colorProgress = flagVariant ? (step === count ? 1 : step === count - 1 ? eased : 0) : 0;
        root.style.setProperty('--rendered-flap-color', mixColor(config.flapColor, euFlagBlue, colorProgress));
        const finalTurn = swapVariant && step === count - 1;
        const movement = finalTurn ? ease(clamp((progress - flagTravelDelay) / (1 - flagTravelDelay), 0, 1)) : eased;
        const swapProgress = swapVariant ? (step === count ? 1 : finalTurn ? movement : 0) : 0;
        const cleanupProgress = swapVariant && (step === count || (finalTurn && progress > 0)) ? 1 : 0;
        const before = models[step], after = models[Math.min(lastModelStep, step + 1)];
        if (swapVariant) updateFlagGeometry(cleanupProgress, cleanupProgress > 0,
            mix(before.get('digit:0').x, after.get('digit:0').x, movement));
        for (const [key, sprite] of sprites) {
            const from = before.get(key), to = after.get(key);
            if (!from && !to) {
                // visibility:hidden is inherited and a child can override it.
                // Remove the entire retired tile from painting, including old
                // moving half-faces, when stepping forward or scrubbing back.
                sprite.group.setAttribute('display', 'none');
                sprite.group.setAttribute('opacity', 0);
                continue;
            }
            let alpha = from && to ? 1 : from ? 1 - eased : eased;
            let x = mix((from || to).x, (to || from).x, movement);
            if (finalTurn && key.startsWith('digit:')) {
                // Close both numeric spacing and painted coverage before travel.
                const column = Number(key.split(':')[1]);
                x = mix(before.get('digit:0').x, after.get('digit:0').x, movement)
                    + column * mix(flapAdvance, tileWidth, cleanupProgress);
            }
            if (swapVariant && step === count && key.startsWith('digit:')) alpha = 0;
            if (finalTurn && (key === 'letter:0' || key === 'letter:1')) {
                // Reverse the reveal, then fade in beside the moving word.
                // Following its spacing keeps a large final gap from placing
                // the reappearing i over another letter. The baseline stays fixed.
                const firstLetterX = mix(before.get('letter:2').x, after.get('letter:2').x, movement) - 2 * characterAdvance;
                if (key === 'letter:0') {
                    alpha = progress < 0.5 ? ease(1 - 2 * progress) : ease(2 * progress - 1);
                    x = progress < 0.5 ? from.x : firstLetterX;
                } else x = firstLetterX + characterAdvance;
            }
            sprite.group.setAttribute('display', alpha > 0 ? 'inline' : 'none');
            sprite.group.setAttribute('opacity', alpha);
            sprite.group.setAttribute('transform', `translate(${x} 0)`);
            if (!sprite.flapped && (!from || !to)) {
                // The outer opacity already handles a new/removed letter.
                // Avoid applying the easing twice through a second fade.
                const character = (from || to).character;
                sprite.draw(character, character, eased);
            } else sprite.draw(from?.character || '', to?.character || '', eased, cleanupProgress);
        }
        const remaining = count - Math.min(count, step);
        root.dataset.state = stateAt(remaining);
        root.dataset.displayState = swapVariant && step === count ? '  ' + word
            : flagVariant && remaining === 0 ? word[0] + '  ' + word.slice(1)
            : stateAt(remaining);
        if (swapVariant) {
            root.dataset.swapProgress = String(swapProgress);
            root.dataset.flagCleanupProgress = String(cleanupProgress);
            renderFlagInteraction(clock());
        }
    }

    function flagSegmentDuration(phase = flagRun.phase) {
        if (phase === 'hold') return config.flagHoldDuration;
        return phase === 'outbound' || phase === 'returning'
            ? motionPreference.matches ? 0 : config.transitionDuration : 0;
    }

    function flagTriggerAvailable() {
        const time = currentTime();
        return swapVariant && ready && !playing
            && time >= expansionEnd && (!hasCollapse || time < collapseStart)
            && flagRun.phase !== 'outbound' && flagRun.phase !== 'returning';
    }

    function resetFlagInteraction() {
        cancelAnimationFrame(flagFrame);
        flagFrame = 0;
        flagRun.phase = 'idle';
    }

    function advanceFlagInteraction(now) {
        // Changing the return mode affects a held country without replaying its fold.
        if (flagRun.phase === 'hold' && config.flagReturnMode === 'manual') flagRun.phase = 'country';
        else if (flagRun.phase === 'country' && config.flagReturnMode === 'auto') {
            flagRun.phase = 'hold';
            flagRun.startedAt = now;
        }
        while (['outbound', 'hold', 'returning'].includes(flagRun.phase)) {
            const segment = flagSegmentDuration();
            if (now - flagRun.startedAt < segment) break;
            flagRun.startedAt += segment;
            if (flagRun.phase === 'outbound') flagRun.phase = config.flagReturnMode === 'auto' ? 'hold' : 'country';
            else if (flagRun.phase === 'hold') flagRun.phase = 'returning';
            else flagRun.phase = 'idle';
        }
    }

    function renderFlagInteraction(now) {
        if (!swapVariant) return;
        const phase = flagRun.phase;
        if (phase === 'idle') drawFlagFold('EU', 'EU', 1);
        else if (phase === 'hold' || phase === 'country') drawFlagFold(flagRun.country, flagRun.country, 1);
        else {
            const span = flagSegmentDuration();
            const progress = span ? ease(clamp((now - flagRun.startedAt) / span, 0, 1)) : 1;
            drawFlagFold(phase === 'outbound' ? 'EU' : flagRun.country,
                phase === 'outbound' ? flagRun.country : 'EU', progress);
        }
        root.dataset.flagInteractionPhase = phase;
    }

    function scheduleFlagFrame() {
        cancelAnimationFrame(flagFrame);
        flagFrame = ['outbound', 'hold', 'returning'].includes(flagRun.phase)
            ? requestAnimationFrame(tickFlagInteraction) : 0;
    }

    function tickFlagInteraction() {
        const now = clock(), previousPhase = flagRun.phase;
        advanceFlagInteraction(now);
        renderFlagInteraction(now);
        if (flagRun.phase !== previousPhase) publish();
        scheduleFlagFrame();
    }

    function triggerFlag() {
        if (!flagTriggerAvailable()) return false;
        const now = clock();
        if (flagRun.phase === 'idle') {
            flagRun.country = config.flagCountry;
            flagRun.phase = 'outbound';
        } else flagRun.phase = 'returning';
        flagRun.startedAt = now;
        advanceFlagInteraction(now);
        renderFlagInteraction(now);
        scheduleFlagFrame();
        publish();
        return true;
    }

    function snapshot() {
        const time = currentTime();
        const returning = sampleReturn(time);
        const atLoopBoundary = config.loop && time >= duration;
        const collapsedHold = hasCollapse && time >= collapseEnd && time < duration;
        const sampled = sample(atLoopBoundary || collapsedHold ? 0 : time);
        const step = returning ? count + (returning.phase === 'text' ? 1 : 2) : sampled.step;
        const progress = returning ? returning.progress : sampled.progress;
        const animationPhase = time >= duration ? 'complete' : collapsedHold ? 'collapsed-hold'
            : returning ? `collapse-${returning.phase}` : time >= expansionEnd ? 'expanded-hold' : 'expansion';
        return {
            type: 'i12e:state', variant, config: { ...config }, duration, loopStartTime,
            currentTime: time, playing, animationPhase,
            step, totalSteps: count + (swapVariant && config.loop ? 2 : 0),
            state: returning && returning.phase === 'flaps' ? 'i12e' : stateAt(count - Math.min(count, step)), reducedMotion: motionPreference.matches,
            ...(swapVariant ? { loopPhase: atLoopBoundary ? 'complete' : collapsedHold ? 'hold' : returning?.phase || 'none' } : {}),
            ...(flagVariant ? { flagPhase: step >= count ? 'flag' : step === count - 1 && progress > 0 ? 'turning' : 'countdown' } : {}),
            ...(swapVariant ? { swapPhase: step === count ? 'complete' : step === count - 1 && progress > 0 ? 'swapping' : 'waiting' } : {}),
            ...(swapVariant ? { flagInteraction: {
                available: flagTriggerAvailable(), phase: flagRun.phase,
                country: flagRun.phase === 'idle' ? config.flagCountry : flagRun.country,
                mode: config.flagReturnMode,
            } } : {}),
            phase: time >= duration ? 'complete' : returning || progress > 0 ? 'transition' : 'hold',
        };
    }
    function publish() {
        const state = snapshot();
        root.dataset.phase = state.phase;
        root.dataset.animationPhase = state.animationPhase;
        root.dataset.playing = String(playing);
        if (window.parent !== window) window.parent.postMessage(state, '*');
    }
    function tick(now) {
        if (!playing) return;
        position = currentTime();
        render(position);
        if (!config.loop && position >= duration) {
            playing = false;
            publish();
            return;
        }
        if (now - lastPublished >= 80) { publish(); lastPublished = now; }
        frame = requestAnimationFrame(tick);
    }
    function play(options = {}) {
        if (!ready) return;
        resetFlagInteraction();
        cancelAnimationFrame(frame);
        position = Number.isFinite(options.time) ? clamp(options.time, 0, duration) : currentTime();
        if (position >= duration) position = 0;
        originTime = position;
        startedAt = Number.isFinite(options.startedAt) ? options.startedAt : clock();
        playing = true;
        render(position);
        frame = requestAnimationFrame(tick);
        publish();
    }
    function pause(time) {
        resetFlagInteraction();
        position = Number.isFinite(time) ? clamp(time, 0, duration) : currentTime();
        playing = false;
        cancelAnimationFrame(frame);
        render(position);
        publish();
    }
    function seek(time) { pause(numeric(time, 0, duration, currentTime())); }
    function seekStep(step) {
        const target = Math.round(numeric(step, 0, count + (swapVariant && config.loop ? 2 : 0), 0));
        seek(target > count ? collapseStart + (target - count - 1) * config.loopDuration / 2
            : target * (config.holdDuration + config.transitionDuration));
    }
    function restart(options = {}) { play({ ...options, time: 0 }); }
    function remapTime(time, previousTiming) {
        const oldExpansionEnd = count * (previousTiming.holdDuration + previousTiming.transitionDuration);
        // Older timing messages used the between-step hold for the completed
        // logotype and wrapped directly after collapse with no collapsed hold.
        const oldExpandedHold = numeric(previousTiming.expandedHoldDuration, 0, 10000, previousTiming.holdDuration);
        const oldCollapseStart = oldExpansionEnd + oldExpandedHold;
        const oldHasCollapse = previousTiming.duration > oldCollapseStart;
        const oldCollapsedHold = oldHasCollapse
            ? numeric(previousTiming.collapsedHoldDuration, 0, previousTiming.duration - oldCollapseStart, 0) : 0;
        const oldCollapseEnd = previousTiming.duration - oldCollapsedHold;
        const oldLoopStart = numeric(previousTiming.loopStartTime, 0, previousTiming.holdDuration, 0);
        const oldTime = oldHasCollapse && time > previousTiming.duration
            ? oldLoopStart + (time - previousTiming.duration) % (previousTiming.duration - oldLoopStart)
            : clamp(time, 0, previousTiming.duration);

        if (oldTime >= previousTiming.duration) {
            // Enabling Loop at a completed expansion starts collapse. A paused
            // loop endpoint remains its exact initial-state render after edits.
            return hasCollapse && !oldHasCollapse ? collapseStart : duration;
        }
        if (oldTime >= oldCollapseStart) {
            if (!hasCollapse || !oldHasCollapse) return collapseStart;
            if (oldCollapsedHold > 0 && oldTime >= oldCollapseEnd) {
                return collapseEnd + (oldTime - oldCollapseEnd) / oldCollapsedHold * config.collapsedHoldDuration;
            }
            return collapseStart + (oldTime - oldCollapseStart)
                / (oldCollapseEnd - oldCollapseStart) * config.loopDuration;
        }
        if (oldTime >= oldExpansionEnd) {
            return expansionEnd + (oldTime - oldExpansionEnd) / oldExpandedHold * config.expandedHoldDuration;
        }
        if (previousTiming.holdDuration === config.holdDuration
            && previousTiming.transitionDuration === config.transitionDuration) return clamp(oldTime, 0, duration);
        // Preserve the fraction of the current hold or transition.
        const cycle = Math.floor(oldTime / (previousTiming.holdDuration + previousTiming.transitionDuration));
        const within = oldTime - cycle * (previousTiming.holdDuration + previousTiming.transitionDuration);
        const offset = within < previousTiming.holdDuration
            ? within / previousTiming.holdDuration * config.holdDuration
            : config.holdDuration + (within - previousTiming.holdDuration) / previousTiming.transitionDuration * config.transitionDuration;
        return clamp(cycle * (config.holdDuration + config.transitionDuration) + offset, 0, duration);
    }

    function configure(next = {}, options = {}) {
        // The reference sends its whole form, plus explicit edit intent.
        // Existing direct callers supplying a colour still make an override.
        const editedColors = Array.isArray(options.editedColors) ? options.editedColors : Object.keys(next);
        for (const key of editedColors) {
            if (key in automaticColors && normalizeColor(next[key])) automaticColors[key] = false;
        }
        const flagTime = clock();
        advanceFlagInteraction(flagTime);
        const flagSpan = flagSegmentDuration();
        const flagProgress = flagSpan ? clamp((flagTime - flagRun.startedAt) / flagSpan, 0, 1) : 0;
        cancelAnimationFrame(flagFrame);
        const resume = typeof options.playing === 'boolean' ? options.playing : playing;
        const time = Number.isFinite(options.time) ? options.time : currentTime();
        // The dashboard supplies the timing basis for its sampled time. This
        // also handles rapid edits before it receives the previous update.
        const supplied = options.timing;
        const previousTiming = supplied
            && [supplied.holdDuration, supplied.transitionDuration, supplied.duration].every(Number.isFinite)
            && supplied.holdDuration >= 0 && supplied.transitionDuration > 0 && supplied.duration > 0
            ? supplied : { holdDuration: config.holdDuration, transitionDuration: config.transitionDuration,
                expandedHoldDuration: config.expandedHoldDuration, loopDuration: config.loopDuration,
                collapsedHoldDuration: config.collapsedHoldDuration, loopStartTime, duration };
        playing = false;
        cancelAnimationFrame(frame);
        config = {
            transitionDuration: numeric(next.transitionDuration ?? config.transitionDuration, 1, 5000, config.transitionDuration),
            holdDuration: numeric(next.holdDuration ?? config.holdDuration, 0, 10000, config.holdDuration),
            expandedHoldDuration: numeric(next.expandedHoldDuration ?? config.expandedHoldDuration, 0, 10000, config.expandedHoldDuration),
            loopDuration: numeric(next.loopDuration ?? config.loopDuration, 1, 10000, config.loopDuration),
            collapsedHoldDuration: numeric(next.collapsedHoldDuration ?? config.collapsedHoldDuration, 0, 10000, config.collapsedHoldDuration),
            easing: typeof next.easing === 'string' && easingFor(next.easing) ? next.easing : config.easing,
            fontSize: numeric(next.fontSize ?? config.fontSize, 12, 96, config.fontSize),
            characterSpacing: numeric(next.characterSpacing ?? config.characterSpacing, 0, 8, config.characterSpacing),
            flapWidth: numeric(next.flapWidth ?? config.flapWidth, 0.6, 2, config.flapWidth),
            flapHeight: numeric(next.flapHeight ?? config.flapHeight, 1, 2.5, config.flapHeight),
            flapGap: numeric(next.flapGap ?? config.flapGap, 0, 0.5, config.flapGap),
            flapOuterGap: numeric(next.flapOuterGap ?? config.flapOuterGap, 0, 96, config.flapOuterGap),
            leadingFlagGap: numeric(next.leadingFlagGap ?? config.leadingFlagGap, 0, 96, config.leadingFlagGap),
            starScale: numeric(next.starScale ?? config.starScale, 0.25, 4, config.starScale),
            flapColor: normalizeColor(next.flapColor) || config.flapColor,
            textColor: normalizeColor(next.textColor) || config.textColor,
            flapTextColor: normalizeColor(next.flapTextColor) || config.flapTextColor,
            detailColor: normalizeColor(next.detailColor) || config.detailColor,
            detailOpacity: numeric(next.detailOpacity ?? config.detailOpacity, 0, 1, config.detailOpacity),
            detailsVisible: typeof next.detailsVisible === 'boolean' ? next.detailsVisible : config.detailsVisible,
            backgroundColor: normalizeColor(next.backgroundColor) || config.backgroundColor,
            loop: typeof next.loop === 'boolean' ? next.loop : config.loop,
            flagCountry: countryFor(next.flagCountry, config.flagCountry),
            flagReturnMode: ['auto', 'manual'].includes(next.flagReturnMode) ? next.flagReturnMode : config.flagReturnMode,
            flagHoldDuration: numeric(next.flagHoldDuration ?? config.flagHoldDuration, 0, 10000, config.flagHoldDuration),
        };
        applyAutomaticColors();
        build();
        position = remapTime(time, previousTiming);
        // Removing an active collapsed hold continues at the next expansion.
        // Editing a paused endpoint must never invoke play()'s replay behaviour.
        if (resume && (position < duration || config.loop)) {
            play({ ...options, time: position >= duration ? loopStartTime : position });
        } else {
            if (position < expansionEnd || (hasCollapse && position >= collapseStart)) resetFlagInteraction();
            else {
                if (flagSpan) flagRun.startedAt = flagTime - flagProgress * flagSegmentDuration();
                advanceFlagInteraction(flagTime);
            }
            render(position);
            scheduleFlagFrame();
            publish();
        }
    }

    async function init() {
        config = readDefaults();
        try { await document.fonts.load(`400 ${config.fontSize}px "Roboto Mono"`, word + '0123456789'); }
        catch { /* A network failure retains the monospaced system fallback. */ }
        build();
        ready = true;
        window.i12e = Object.freeze({ play, pause, restart, seek, seekStep, configure, triggerFlag, getState: snapshot });
        window.addEventListener('message', event => {
            if (event.source !== window.parent || event.data?.type !== 'i12e:command') return;
            const data = event.data;
            if (data.action === 'configure') configure(data.config, data);
            else if (data.action === 'appearance') applyAppearance(data);
            else if (data.action === 'seek') seek(data.time);
            else if (data.action === 'seekStep') seekStep(data.step);
            else if (data.action === 'play') play(data);
            else if (data.action === 'pause') pause(data.time);
            else if (data.action === 'restart') restart(data);
            else if (data.action === 'triggerFlag') triggerFlag();
            else if (data.action === 'status') publish();
        });
        motionPreference.addEventListener('change', event => { if (event.matches) seek(duration); });
        if (motionPreference.matches) seek(duration);
        else if (params.get('autoplay') === '0') seek(0);
        else play();
    }
    if (document.readyState === 'complete') init();
    else window.addEventListener('load', init, { once: true });
})();
